#!/usr/bin/env python3
"""Generate MoonBit tables for suica/jxl/moxcms/pxfm from pxfm-0.1.30 sources.

Usage: gen_tables.py <pxfm-0.1.30/src> <out_dir>  (see regen.sh)
"""
import re, sys, os

SRC, OUT = sys.argv[1], sys.argv[2]

def strip_comments(s):
    s = re.sub(r'/\*.*?\*/', '', s, flags=re.S)
    s = re.sub(r'//[^\n]*', '', s)
    return s

def find_array(path, name, kind_decl):
    """Return body text of `<kind_decl> NAME: [T; N] = [ ... ]`, plus N."""
    s = strip_comments(open(os.path.join(SRC, path)).read())
    m = re.search(kind_decl + r'\s+' + name + r'\s*:\s*\[(.*?);\s*(\d+)\]\s*=\s*', s)
    if not m and name == 'EXP2FT':
        m = re.search(r'static EXP2FT: Exp2Table = ()()', s)
        typ, n = '(u32, u32)', 64
    elif not m and name == 'LOG_REDUCTION_F32':
        m = re.search(r'static LOG_REDUCTION_F32: LogReductionF32Aligned = ()()', s)
        typ, n = 'u32', 128
    else:
        assert m, (path, name)
        typ, n = m.group(1).strip(), int(m.group(2))
    i = m.end()
    if s.startswith('Exp2Table(', i):
        i += len('Exp2Table(')
    if s.startswith('LogReductionF32Aligned(', i):
        i += len('LogReductionF32Aligned(')
    assert s[i] == '[', (path, name, s[i:i+20])
    depth = 0
    for j in range(i, len(s)):
        if s[j] == '[': depth += 1
        elif s[j] == ']':
            depth -= 1
            if depth == 0:
                return typ, n, s[i+1:j]
    raise Exception('unterminated')

def hexes(body):
    return [int(t.replace('_', ''), 16) for t in re.findall(r'0x[0-9a-fA-F_]+', body)]

def emit_u64(name, vals, per_line, comment):
    out = ['///|', '/// ' + comment, 'let %s : FixedArray[UInt64] = [' % name]
    for k in range(0, len(vals), per_line):
        out.append('  ' + ' '.join('0x%016x_UL,' % v for v in vals[k:k+per_line]).replace('_UL', 'UL'))
    out.append(']')
    return '\n'.join(out) + '\n'

def emit_u32(name, vals, comment):
    out = ['///|', '/// ' + comment, 'let %s : FixedArray[UInt] = [' % name]
    for k in range(0, len(vals), 4):
        out.append('  ' + ' '.join('0x%08xU,' % v for v in vals[k:k+4]))
    out.append(']')
    return '\n'.join(out) + '\n'

def emit_i32(name, vals, comment):
    out = ['///|', '/// ' + comment, 'let %s : FixedArray[Int] = [' % name]
    for k in range(0, len(vals), 10):
        out.append('  ' + ' '.join('%d,' % v for v in vals[k:k+10]))
    out.append(']')
    return '\n'.join(out) + '\n'

def emit_dyadic(name, body, n, comment):
    ents = re.findall(r'sign:\s*DyadicSign::(Pos|Neg),\s*exponent:\s*(-?\d+),\s*mantissa:\s*(0x[0-9a-fA-F_]+|0)_?u128', body)
    assert len(ents) == n, (name, len(ents), n)
    out = ['///|', '/// ' + comment, 'let %s : FixedArray[DyadicFloat128] = [' % name]
    for sg, e, mant in ents:
        m = int(mant.replace('_', ''), 16) if mant.startswith('0x') else 0
        out.append('  dyadic_const(%s, %s, 0x%016xUL, 0x%016xUL),' % (
            'true' if sg == 'Neg' else 'false', e, m >> 64, m & ((1 << 64) - 1)))
    out.append(']')
    return '\n'.join(out) + '\n'

HDR = ('// Tables of pxfm 0.1.30 (https://github.com/awxkee/pxfm),\n'
       '// Copyright (c) Radzivon Bartoshyk. BSD-3-Clause OR Apache-2.0.\n//\n') + '// Generated by gen_tables.py from pxfm 0.1.30 `%s`. Do not edit.\n// Tuple tables are flattened in Rust tuple order (.0, .1[, .2]).\n\n'

def table(path, name, mbt, kind='static', comment=None):
    t, n, body = find_array(path, name, r'(?:pub\(crate\)\s+)?' + kind)
    comment = comment or ('`%s` from `%s` (%s; %d)' % (name, path, t, n))
    if t == 'DyadicFloat128':
        return emit_dyadic(mbt, body, n, comment)
    v = hexes(body) if t != 'i32' else None
    if t == 'u64':
        assert len(v) == n, (name, len(v), n); return emit_u64(mbt, v, 2, comment)
    if t == '(u64, u64)':
        assert len(v) == 2 * n, (name, len(v), n); return emit_u64(mbt, v, 2, comment)
    if t == '(u64, u64, u64)':
        assert len(v) == 3 * n, (name, len(v), n); return emit_u64(mbt, v, 3, comment)
    if t == 'u32':
        assert len(v) == n, (name, len(v), n); return emit_u32(mbt, v, comment)
    if t == '(u32, u32)':
        assert len(v) == 2 * n, (name, len(v), n); return emit_u32(mbt, v, comment)
    if t == 'i32':
        toks = re.findall(r'-?0x[0-9a-fA-F]+', body)
        vals = [int(x, 16) for x in toks]
        assert len(vals) == n, (name, len(vals), n); return emit_i32(mbt, vals, comment)
    raise Exception(t)

files = {
  'exp_tables.mbt': ('exponents/exp.rs', [
      ('exponents/exp.rs', 'EXP_REDUCE_T0', 'exp_reduce_t0', 'static'),
      ('exponents/exp.rs', 'EXP_REDUCE_T1', 'exp_reduce_t1', 'static'),
      ('exponents/exp2f.rs', 'EXP2FT', 'exp2ft', 'static'),
  ]),
  'pow_tables.mbt': ('pow_tables.rs', [
      ('pow_tables.rs', 'POW_INVERSE', 'pow_inverse', 'static'),
      ('pow_tables.rs', 'POW_LOG_INV', 'pow_log_inv', 'static'),
      ('pow_tables.rs', 'EXP2_MID1', 'exp2_mid1', 'static'),
      ('pow_tables.rs', 'EXP_T1_2_DYADIC', 'exp_t1_2_dyadic', 'static'),
      ('pow_tables.rs', 'EXP_T2_2_DYADIC', 'exp_t2_2_dyadic', 'static'),
  ]),
  'powf_tables.mbt': ('powf_tables.rs', [
      ('powf_tables.rs', 'POWF_R2', 'powf_r2', 'static'),
      ('powf_tables.rs', 'LOG2_R_TD', 'log2_r_td', 'static'),
      ('powf_tables.rs', 'LOG2_R2_DD', 'log2_r2_dd', 'static'),
      ('logs/log2f.rs', 'LOG2_R', 'log2_r', 'static'),
      ('logs/logf.rs', 'LOG_REDUCTION_F32', 'log_reduction_f32', 'static'),
  ]),
  'log_tables.mbt': ('logs/*.rs', [
      ('logs/log2.rs', 'LOG_RANGE_REDUCTION', 'log_range_reduction_table', 'static'),
      ('logs/log2.rs', 'LOG_CD', 'log_cd', 'static'),
      ('logs/log2.rs', 'LOG_COEFFS', 'log_coeffs', 'const'),
      ('logs/log10.rs', 'LOG_R_DD', 'log_r_dd', 'static'),
      ('logs/log_dd_coeffs.rs', 'LOG_NEG_DD', 'log_neg_dd', 'static'),
      ('logs/log_td_table.rs', 'LOG_NEG_TD', 'log_neg_td', 'static'),
      ('logs/log10dd_coeffs.rs', 'LOG10_NEG_DD', 'log10_neg_dd', 'static'),
      ('logs/log10td_coeffs.rs', 'LOG10_NEG_TD', 'log10_neg_td', 'static'),
      ('logs/log_dd.rs', 'P', 'log_dd_poly_p', 'const'),
      ('logs/log_td.rs', 'P', 'log_td_poly_p', 'const'),
      ('logs/log10dd.rs', 'P', 'log10_dd_poly_p', 'const'),
      ('logs/log10td.rs', 'P', 'log10_td_poly_p', 'const'),
      ('logs/log_range_reduction.rs', 'S2', 'log_rr_s2', 'static'),
      ('logs/log_range_reduction.rs', 'S3', 'log_rr_s3', 'static'),
      ('logs/log_range_reduction.rs', 'S4', 'log_rr_s4', 'static'),
  ]),
  'log_dyadic_tables.mbt': ('logs/log_dyadic.rs', [
      ('logs/log_dyadic.rs', 'LOG_STEP_1', 'log_step_1', 'static'),
      ('logs/log_dyadic.rs', 'LOG_STEP_2', 'log_step_2', 'static'),
      ('logs/log_dyadic.rs', 'LOG_STEP_3', 'log_step_3', 'static'),
      ('logs/log_dyadic.rs', 'LOG_STEP_4', 'log_step_4', 'static'),
  ]),
}
for fn, (src, lst) in files.items():
    with open(os.path.join(OUT, fn), 'w') as f:
        f.write(HDR % src)
        f.write('\n'.join(table(p, n, m, k) for p, n, m, k in lst))
    print('wrote', fn)
